CREATE TABLE supply_matches(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`request_id` BIGINT  NOT NULL,`listing_id` BIGINT  NULL,`farmer_id` BIGINT  NOT NULL,`matched_quantity` DECIMAL(10,2)  NOT NULL,`match_score` DECIMAL(5,2)  NULL,`price_offered` DECIMAL(10,2)  NULL,`status` varchar(50)  NOT NULL DEFAULT 'suggested',`match_explanation` text  NULL,`is_aggregated` TINYINT(1)  NOT NULL DEFAULT 0,`aggregation_group_id` varchar(100)  NULL,`farmer_confirmation_status` varchar(50)  NOT NULL DEFAULT 'pending',`farmer_confirmed_at` timestamp  NULL,`buyer_accepted_at` timestamp  NULL,`delivery_status` varchar(50)  NOT NULL DEFAULT 'pending',`delivery_notes` text  NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;